  const createDive = async () => {
    if (submitting.current || !validate()) return;
    submitting.current = true;
    setSaving(true);
    setSubmitError('');
    const dateObj = new Date(0);
    dateObj.setFullYear(Number(year), Number(month) - 1, Number(day));
    dateObj.setHours(Number(hour || 0), 0, 0, 0);

    try {
