  },

  webGroupSection: {
    flexDirection: 'row',
    flexWrap: 'nowrap',
    alignItems: 'stretch',
    marginHorizontal: -12,
  } as any,

  groupHeader: {
    backgroundColor: '#f2f8ff',
    borderRadius: 14,
    padding: 14,
    marginBottom: 10,
  },

  webGroupHeader: {
    width: 150,
