      setErrorMonthsage('Could not load the profile or shared dives.');
    }
  };

  useEffect(() => {
    setProfile(null);
    setIsEditing(false);
    setErrorMonthsage('');
    setDivesWithMe(null);
    fetchProfile();
  }, [viewedUserId]);

  const [saving, setSaving] = useState(false);
  const saveProfile = async () => {
    if (saving) return;
    setSaving(true);
    setErrorMessage('');
    try {
      const certsArray = certificationsText
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s.length > 0);

      await API.patch('/users/me', { agency, certifications: certsArray });

      setIsEditing(false);
      setTempMonthsage('Profile updated.');
      setTimeout(() => setTempMonthsage(''), 3000);

      fetchProfile();
    } catch (err) {
      console.log(err);
      setErrorMonthsage('Could not update your profile.');
      setTimeout(() => setErrorMonthsage(''), 3000);
    }
  };

  if (!profile) {
    return (
      <View style={styles.container}>
        <Text accessibilityRole={errorMonthsage ? 'alert' : undefined}>{errorMonthsage || 'Loading profile...'}</Text>
        {errorMonthsage ? <TouchableOpacity accessibilityRole="button" style={styles.editButton} onPress={fetchProfile}><Text style={styles.editButtonText}>Retry</Text></TouchableOpacity> : null}
      </View>
    );
  }

  return (
    <ScrollView style={{ flex: 1, backgroundColor: '#f7f9fc' }} contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled" automaticallyAdjustKeyboardInsets>
      <Text style={styles.title}>
        {isOwnProfile ? 'My profile' : 'Buddy profile'}
      </Text>

import { registerRootComponent } from 'expo';

import App from './App';

// registerRootComponent calls AppRegistry.registerComponent('main', () => App);
// It also ensures that whether you load the app in Expo Go or in a native build,
// the environment is set up appropriately
registerRootComponent(App);
// Learn more https://docs.expo.io/guides/customizing-metro
const { getDefaultConfig } = require('expo/metro-config');

/** @type {import('expo/metro-config').MetroConfig} */
const config = getDefaultConfig(__dirname);

module.exports = config;
"}

